package in.aicon.pocket;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import org.json.*;
/** Canonical app records for an explicit transfer. No Google tokens, row IDs or device state. */
public final class LedgerRecords {private LedgerRecords(){}
 public static Map<String,String> capture(SQLiteDatabase db,CatalogStore catalog,SettingsStore settings)throws Exception{
  if(!db.inTransaction())throw new IllegalStateException("Canonical snapshot requires a ledger transaction");Map<String,String> result=new TreeMap<>();Map<String,Map<String,String>> refs=new HashMap<>();
  List<String> budgetCategories=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT category FROM budgets",null)){while(c.moveToNext())budgetCategories.add(c.getString(0));}catalog.seed(new String[]{},new String[]{});for(String category:budgetCategories)catalog.ensureReference("category",category,27);for(String type:CatalogStore.TYPES){Map<String,String> names=new HashMap<>();refs.put(type,names);for(CatalogStore.Item item:catalog.list(type)){names.put(item.name,item.id);if(result.put(item.id,LedgerWire.catalog(item).toString())!=null)throw new IllegalArgumentException("Duplicate catalog ID");}}if(result.put(LedgerWire.PREFERENCES_ID,LedgerWire.preferences(settings.export()).toString())!=null)throw new IllegalArgumentException("Catalog uses reserved preference ID");
  try(Cursor c=db.rawQuery("SELECT uuid,kind,amount,day,account,dest,category,note,person,loan FROM tx",null)){while(c.moveToNext()){JSONObject j=LedgerWire.linkedTransaction(c.getString(0),c.getString(1),c.getLong(2),c.getString(3),ref(refs,"account",c.getString(4)),ref(refs,"account",c.getString(5)),c.getString(6).equals("Debt")||c.getString(6).equals("Transfer")?c.getString(6):ref(refs,"category",c.getString(6)),c.getString(7),ref(refs,"person",c.getString(8)),c.getString(9)).put("currency",settings.get("currency"));if(result.put(c.getString(0),j.toString())!=null)throw new IllegalArgumentException("Duplicate financial ID");}}
  try(Cursor c=db.rawQuery("SELECT uuid,category,amount FROM budgets",null)){while(c.moveToNext()){JSONObject j=LedgerWire.linkedBudget(c.getString(0),ref(refs,"category",c.getString(1)),c.getLong(2)).put("currency",settings.get("currency"));if(result.put(j.getString("uuid"),j.toString())!=null)throw new IllegalArgumentException("Duplicate financial ID");}}
  try(Cursor c=db.rawQuery("SELECT uuid,name,target,saved FROM goals",null)){while(c.moveToNext()){JSONObject j=LedgerWire.goal(c.getString(0),c.getString(1),c.getLong(2),c.getLong(3)).put("currency",settings.get("currency"));if(result.put(c.getString(0),j.toString())!=null)throw new IllegalArgumentException("Duplicate financial ID");}}
  return result;
 }
 private static String ref(Map<String,Map<String,String>> refs,String type,String name){if(name.isEmpty())return "";String id=refs.get(type).get(name);if(id==null)throw new IllegalArgumentException("Missing catalog entry: "+type);return id;}
}
